<script>
import { useForm } from '@inertiajs/vue3';
import Card from './Card.vue';
import Modal from './Modal.vue';
import InputError from './InputError.vue';
import { destroy } from '@app/routes/profile';
import { destroy as destroyUser } from '@app/routes/admin/users';

export default {
    components: { Card, Modal, InputError },
    props: { user: Object, disabled: Boolean },
    data: () => ({ form: useForm({ password: '', confirmation: true }) }),
    methods: {
        open() {
            this.form.resetAndClearErrors();
            this.$refs.modal.show();
        },
        remove() {
            if (this.disabled || this.form.processing) return;
            this.form.delete(
                this.user ? destroyUser.url(this.user.id) : destroy.url(),
                {
                    preserveScroll: true,
                    onError: () => this.form.reset('password'),
                    onSuccess: () => this.$refs.modal?.hide(),
                },
            );
        },
    },
};
</script>

<template>
    <Card
        :title="user ? 'Dzēst lietotāju' : 'Dzēst kontu'"
        icon="person_remove"
        card-header-class="card-header-danger"
    >
        <p>
            Personas dati tiks anonimizēti, piekļuve slēgta. Saistītie ieraksti
            saglabāsies ar anonimizētu autoru. Lietotājs šo darbību nevar
            atsaukt.
        </p>
        <button
            type="button"
            class="btn btn-danger"
            :disabled="disabled || form.processing"
            @click="open"
        >
            {{ user ? 'Dzēst lietotāju' : 'Dzēst manu kontu' }}
        </button>
        <Modal
            ref="modal"
            title="Apstiprināt konta dzēšanu"
            :footer-close="false"
            @close="form.resetAndClearErrors()"
        >
            <form @submit.prevent="remove">
                <p>
                    Vai tiešām dzēst {{ user ? user.name : 'savu kontu' }}?
                    Personas datu anonimizēšana ir neatgriezeniska.
                </p>
                <div v-if="!user" class="form-group">
                    <label for="delete-account-password"
                        >Pašreizējā parole</label
                    >
                    <input
                        id="delete-account-password"
                        v-model="form.password"
                        type="password"
                        class="form-control"
                        autocomplete="current-password"
                        required
                        :disabled="form.processing"
                    />
                    <InputError :message="form.errors.password" />
                </div>
                <InputError
                    :message="form.errors.account || form.errors.confirmation"
                />
                <button
                    type="submit"
                    class="btn btn-danger"
                    :disabled="disabled || form.processing"
                >
                    {{ form.processing ? 'Dzēš…' : 'Jā, dzēst kontu' }}
                </button>
            </form>
        </Modal>
    </Card>
</template>
