<template>
    <Card v-if="canManageTwoFactor" title="Divu faktoru autentifikācija" icon="security" card-header-class="card-header-info">
        <p>Piesakoties ievadīsiet arī vienreizēju kodu no autentifikatora lietotnes.</p>
        <p role="status">{{ enabled ? 'Divu faktoru autentifikācija ir ieslēgta.' : 'Divu faktoru autentifikācija nav ieslēgta.' }}</p>
        <p v-if="error" class="text-danger" role="alert">{{ error }}</p>
        <p v-if="notice" class="text-success" role="status">{{ notice }}</p>
        <Link v-if="needsConfirmation" :href="securityUrl" class="btn btn-primary">Apstiprināt paroli vēlreiz</Link>

        <div v-if="setupPending">
            <p>Noskenējiet QR kodu autentifikatora lietotnē vai ievadiet iestatīšanas atslēgu manuāli.</p>
            <div v-if="qrSvg" class="two-factor-qr mx-auto mb-3" role="img" aria-label="Autentifikatora iestatīšanas QR kods" v-html="qrSvg"></div>
            <label v-if="secret" for="two-factor-secret">Iestatīšanas atslēga</label>
            <input v-if="secret" id="two-factor-secret" :value="secret" class="form-control font-monospace mb-3" readonly autocomplete="off" spellcheck="false">
            <button v-if="!qrSvg || !secret" type="button" class="btn btn-info btn-sm" :disabled="busy" @click="run(loadSetup)">Ielādēt iestatīšanas datus vēlreiz</button>
            <form v-if="requiresConfirmation && qrSvg && secret" @submit.prevent="run(confirmSetup)">
                <label for="two-factor-code">Sešciparu kods</label>
                <input id="two-factor-code" ref="codeInput" v-model="confirmation.code" type="text" class="form-control" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required :disabled="busy" :aria-invalid="Boolean(confirmation.errors.code)" aria-describedby="two-factor-code-error">
                <InputError id="two-factor-code-error" :message="confirmation.errors.code" />
                <button type="submit" class="btn btn-primary" :disabled="busy">Apstiprināt un ieslēgt</button>
            </form>
            <button v-if="!requiresConfirmation && qrSvg && secret" type="button" class="btn btn-primary" :disabled="busy" @click="run(confirmSetup)">Pabeigt iestatīšanu</button>
            <button type="button" class="btn btn-link btn-danger" :disabled="busy" @click="run(cancelSetup)">Atcelt iestatīšanu</button>
        </div>
        <button v-else-if="!enabled" type="button" class="btn btn-primary" :disabled="busy" @click="run(beginSetup)">Iestatīt divu faktoru autentifikāciju</button>

        <div v-if="enabled && !setupPending">
            <p>Saglabājiet atkopšanas kodus drošā vietā. Katru kodu var izmantot vienu reizi, ja nav pieejams autentifikators.</p>
            <div class="d-flex flex-wrap gap-2">
                <button type="button" class="btn btn-info btn-sm" :disabled="busy" @click="codes.length ? hideCodes() : run(loadRecoveryCodes)">{{ codes.length ? 'Paslēpt atkopšanas kodus' : 'Rādīt atkopšanas kodus' }}</button>
                <button type="button" class="btn btn-danger btn-sm" :disabled="busy" @click="$refs.disableModal.show()">Izslēgt 2FA</button>
            </div>
            <div v-if="codes.length" class="mt-3">
                <label for="two-factor-recovery-codes">Atkopšanas kodi</label>
                <textarea id="two-factor-recovery-codes" ref="recoveryCodesInput" class="form-control font-monospace" :value="codes.join('\n')" :rows="codes.length" readonly autocomplete="off" spellcheck="false"></textarea>
                <button type="button" class="btn btn-primary btn-sm" @click="copyCodes">Kopēt kodus</button>
                <p class="fg-2">Ģenerējot jaunus kodus, iepriekšējie kļūs nederīgi.</p>
                <button type="button" class="btn btn-warning btn-sm" :disabled="busy" @click="run(regenerateCodes)">Ģenerēt jaunus kodus</button>
            </div>
        </div>
        <p v-if="busy" class="fg-2" role="status">Lūdzu, uzgaidiet…</p>

        <Modal ref="disableModal" title="Izslēgt divu faktoru autentifikāciju?" :footer-close="false">
            <p>Piesakoties vairs nebūs jāievada autentifikatora kods. Esošie atkopšanas kodi kļūs nederīgi.</p>
            <p v-if="error" class="text-danger" role="alert">{{ error }}</p>
            <template #footer>
                <button type="button" class="btn btn-link" :disabled="busy" @click="$refs.disableModal.hide()">Atcelt</button>
                <button type="button" class="btn btn-danger" :disabled="busy" @click="run(disableAuthentication)">Izslēgt 2FA</button>
            </template>
        </Modal>
    </Card>
</template>

<script>
import { Link, useHttp } from '@inertiajs/vue3';
import Card from './Card.vue';
import InputError from './InputError.vue';
import Modal from './Modal.vue';
import { confirm, disable, enable, qrCode, recoveryCodes, regenerateRecoveryCodes, secretKey } from '@app/routes/two-factor';
import { edit } from '@app/routes/security';

export default {
    name: 'ManageTwoFactor',
    components: { Card, InputError, Link, Modal },
    emits: ['setup-change'],
    props: {
        canManageTwoFactor: Boolean,
        twoFactorEnabled: Boolean,
        requiresConfirmation: Boolean,
    },
    data() {
        return {
            enabled: this.twoFactorEnabled,
            setupPending: false,
            busy: false,
            disposed: false,
            needsConfirmation: false,
            qrSvg: '',
            secret: '',
            codes: [],
            notice: '',
            error: '',
            request: useHttp({}),
            confirmation: useHttp({ code: '' }),
            securityUrl: edit.url(),
        };
    },
    beforeUnmount() {
        this.disposed = true;
        this.request.cancel();
        this.confirmation.cancel();
        this.clearSetup();
        this.hideCodes();
    },
    watch: {
        setupPending(value) {
            this.$emit('setup-change', value);
        },
    },
    methods: {
        async run(operation) {
            if (this.busy) {
                return;
            }
            this.busy = true;
            this.error = '';
            this.notice = '';
            this.needsConfirmation = false;
            try {
                await operation();
            } catch (error) {
                if (this.disposed) {
                    return;
                }
                this.needsConfirmation = error.response?.status === 423;
                this.error = this.needsConfirmation
                    ? 'Paroles apstiprinājuma termiņš ir beidzies. Apstipriniet paroli un atkārtojiet darbību.'
                    : 'Darbību neizdevās pabeigt. Lūdzu, mēģiniet vēlreiz.';
            } finally {
                this.busy = false;
            }
        },
        async call(route) {
            this.request.clearErrors();
            try {
                const result = await this.request.submit(route);
                if (this.disposed || this.request.hasErrors) {
                    throw new Error('Two-factor request failed');
                }
                return result;
            } finally {
                this.request.response = null;
            }
        },
        async beginSetup() {
            await this.call(enable());
            this.enabled = !this.requiresConfirmation;
            this.setupPending = true;
            await this.loadSetup();
        },
        async loadSetup() {
            const qr = await this.call(qrCode());
            const key = await this.call(secretKey());
            if (!qr?.svg || !key?.secretKey) {
                throw new Error('Missing two-factor setup data');
            }
            this.qrSvg = qr.svg;
            this.secret = key.secretKey;
            await this.$nextTick();
            this.$refs.codeInput?.focus();
        },
        async confirmSetup() {
            if (this.requiresConfirmation) {
                this.confirmation.clearErrors();
                await this.confirmation.post(confirm.url());
                this.confirmation.code = '';
                this.confirmation.response = null;
                if (this.disposed || this.confirmation.hasErrors) {
                    return;
                }
            }
            this.enabled = true;
            this.clearSetup();
            await this.loadRecoveryCodes();
            this.notice = 'Divu faktoru autentifikācija ieslēgta. Saglabājiet atkopšanas kodus.';
        },
        async cancelSetup() {
            await this.call(disable());
            this.enabled = false;
            this.clearSetup();
            this.hideCodes();
            this.notice = 'Iestatīšana atcelta.';
        },
        async disableAuthentication() {
            await this.call(disable());
            this.enabled = false;
            this.clearSetup();
            this.hideCodes();
            await this.$refs.disableModal.hide();
            this.notice = 'Divu faktoru autentifikācija izslēgta.';
        },
        async loadRecoveryCodes() {
            const codes = await this.call(recoveryCodes());
            if (!Array.isArray(codes)) {
                throw new Error('Invalid recovery codes response');
            }
            this.codes = codes;
        },
        async regenerateCodes() {
            this.hideCodes();
            await this.call(regenerateRecoveryCodes());
            await this.loadRecoveryCodes();
            this.notice = 'Izveidoti jauni atkopšanas kodi. Iepriekšējie vairs nav derīgi.';
        },
        hideCodes() {
            this.codes = [];
            this.request.response = null;
        },
        clearSetup() {
            this.setupPending = false;
            this.qrSvg = '';
            this.secret = '';
            this.confirmation.defaults({ code: '' });
            this.confirmation.resetAndClearErrors();
            this.confirmation.response = null;
        },
        async copyCodes() {
            try {
                await navigator.clipboard.writeText(this.codes.join('\n'));
                this.notice = 'Atkopšanas kodi nokopēti.';
            } catch {
                this.$refs.recoveryCodesInput?.focus();
                this.$refs.recoveryCodesInput?.select();
                this.notice = 'Kodi iezīmēti. Kopējiet tos ar Ctrl+C vai Cmd+C.';
            }
        },
    },
};
</script>

<style scoped>
.two-factor-qr {
    width: min(100%, 224px);
    padding: 12px;
    background: #fff;
    border-radius: var(--radius-2);
}

.two-factor-qr :deep(svg) {
    display: block;
    width: 100%;
    height: auto;
}
</style>
