<script>
import { useForm } from '@inertiajs/vue3';
import Card from './Card.vue';
import Modal from './Modal.vue';
import { destroy } from '@app/routes/sessions';

export default {
    components: { Card, Modal },
    props: { sessions: { type: Array, default: () => [] }, disabled: Boolean },
    data: () => ({ form: useForm({ session_id: null }), selected: null }),
    methods: {
        confirm(session = null) {
            this.selected = session;
            this.form.clearErrors();
            this.$refs.confirmModal.show();
        },
        revoke() {
            if (this.disabled || this.form.processing) return;
            this.form.session_id = this.selected?.id || null;
            this.form.delete(destroy.url(), {
                preserveScroll: true,
                onSuccess: () => this.$refs.confirmModal.hide(),
            });
        },
    },
};
</script>

<template>
    <Card
        title="Aktīvās sesijas"
        icon="devices"
        card-header-class="card-header-primary"
    >
        <p>
            Sesijas citās pārlūkprogrammās un ierīcēs. Ierīces aprakstu sniedz
            pārlūkprogramma.
        </p>
        <div
            v-for="session in sessions"
            :key="session.id"
            class="d-flex justify-content-between align-items-center gap-3 mb-3"
        >
            <div class="session-details">
                <strong>{{
                    session.is_current ? 'Šī ierīce' : session.ip_address
                }}</strong>
                <div>
                    {{ session.user_agent || 'Nezināma pārlūkprogramma' }}
                </div>
                <small class="fg-2"
                    >{{ session.ip_address }} · {{ session.last_active }}</small
                >
            </div>
            <button
                v-if="!session.is_current"
                type="button"
                class="btn btn-link btn-danger"
                :disabled="disabled || form.processing"
                @click="confirm(session)"
            >
                Izrakstīt
            </button>
        </div>
        <button
            type="button"
            class="btn btn-primary"
            :disabled="
                disabled ||
                form.processing ||
                !sessions.some((session) => !session.is_current)
            "
            @click="confirm()"
        >
            Izrakstīt pārējās ierīces
        </button>
        <p v-if="form.errors.sessions" class="text-danger" role="alert">
            {{ form.errors.sessions }}
        </p>
        <Modal
            ref="confirmModal"
            title="Izrakstīt ierīces"
            :footer-close="false"
        >
            <p>
                {{
                    selected
                        ? 'Vai izrakstīt izvēlēto ierīci?'
                        : 'Vai izrakstīt visas pārējās ierīces?'
                }}
                Šī sesija paliks aktīva.
            </p>
            <template #footer
                ><button
                    type="button"
                    class="btn btn-danger"
                    :disabled="disabled || form.processing"
                    @click="revoke"
                >
                    Apstiprināt
                </button></template
            >
        </Modal>
    </Card>
</template>

<style scoped>
.session-details {
    min-width: 0;
    overflow-wrap: anywhere;
}
</style>
