<script>
import { Passkeys, UserCancelledError } from '@laravel/passkeys';
import { router, useHttp, Link } from '@inertiajs/vue3';
import Card from './Card.vue';
import Modal from './Modal.vue';
import {
    index,
    store,
    destroy,
} from '@app/actions/Laravel/Passkeys/Http/Controllers/PasskeyRegistrationController';
import { edit } from '@app/routes/security';

export default {
    components: { Card, Modal, Link },
    props: { passkeys: { type: Array, default: () => [] }, disabled: Boolean },
    data: () => ({
        supported: false,
        busy: false,
        name: '',
        error: '',
        selected: null,
        disposed: false,
        needsConfirmation: false,
        request: useHttp({}),
        securityUrl: edit.url(),
    }),
    mounted() {
        this.supported = window.isSecureContext && Passkeys.isSupported();
    },
    beforeUnmount() {
        this.disposed = true;
        this.request.cancel();
        if (this.busy) Passkeys.cancel();
    },
    methods: {
        async register() {
            if (this.disabled || this.busy || !this.name.trim()) return;
            this.busy = true;
            this.error = '';
            try {
                await Passkeys.register({
                    name: this.name.trim(),
                    routes: { options: index.url(), submit: store.url() },
                });
                if (!this.disposed) {
                    this.name = '';
                    router.reload({ only: ['passkeys'], preserveScroll: true });
                }
            } catch (error) {
                if (!this.disposed)
                    this.error =
                        error instanceof UserCancelledError
                            ? 'Darbība atcelta.'
                            : 'Atslēgu neizdevās pievienot. Ja apstiprinājuma laiks beidzies, atveriet drošības iestatījumus atkārtoti.';
            } finally {
                this.busy = false;
            }
        },
        remove(passkey) {
            this.selected = passkey;
            this.error = '';
            this.$refs.removeModal.show();
        },
        async confirmRemove() {
            if (!this.selected || this.busy || this.disabled) return;
            this.busy = true;
            try {
                await this.request.submit(destroy(this.selected.id));
                if (this.request.hasErrors) throw new Error();
                if (!this.disposed) {
                    await this.$refs.removeModal.hide();
                    router.reload({ only: ['passkeys'], preserveScroll: true });
                }
            } catch (error) {
                this.needsConfirmation = error.response?.status === 423;
                this.error = 'Atslēgu neizdevās dzēst. Mēģiniet vēlreiz.';
            } finally {
                this.busy = false;
                this.request.response = null;
            }
        },
    },
};
</script>

<template>
    <Card
        title="Piekļuves atslēgas"
        icon="key"
        card-header-class="card-header-primary"
    >
        <p>Piesakieties ar Windows Hello, Touch ID vai drošības atslēgu.</p>
        <p v-if="!passkeys.length" class="fg-2">Piekļuves atslēgu vēl nav.</p>
        <div
            v-for="passkey in passkeys"
            :key="passkey.id"
            class="d-flex align-items-center justify-content-between gap-3 mb-3"
        >
            <div>
                <strong>{{ passkey.name }}</strong>
                <div class="fg-2">
                    Izveidota {{ passkey.created_at_diff }} ·
                    {{
                        passkey.last_used_at_diff
                            ? `Izmantota ${passkey.last_used_at_diff}`
                            : 'Vēl nav izmantota'
                    }}
                </div>
            </div>
            <button
                type="button"
                class="btn-icon text-danger"
                :disabled="disabled || busy"
                :aria-label="`Dzēst ${passkey.name}`"
                @click="remove(passkey)"
            >
                <i class="material-icons" aria-hidden="true">delete</i>
            </button>
        </div>
        <form v-if="supported" @submit.prevent="register">
            <label for="passkey-name">Atslēgas nosaukums</label>
            <input
                id="passkey-name"
                v-model="name"
                class="form-control"
                maxlength="255"
                required
                :disabled="busy || disabled"
                placeholder="Mans dators"
            />
            <button
                type="submit"
                class="btn btn-primary"
                :disabled="busy || disabled || !name.trim()"
            >
                {{ busy ? 'Uzgaidiet…' : 'Pievienot atslēgu' }}
            </button>
        </form>
        <p v-else class="fg-2">
            Lai pievienotu atslēgu, izmantojiet HTTPS un saderīgu
            pārlūkprogrammu.
        </p>
        <p v-if="error" class="text-danger" role="alert">{{ error }}</p>
        <Link v-if="needsConfirmation" :href="securityUrl"
            >Atkārtoti apstiprināt piekļuvi</Link
        >
        <Modal
            ref="removeModal"
            title="Dzēst piekļuves atslēgu"
            :footer-close="false"
        >
            <p>
                Vai dzēst atslēgu “{{ selected?.name }}”? Šī atslēga vairs
                nederēs, lai pieteiktos.
            </p>
            <p v-if="error" class="text-danger" role="alert">{{ error }}</p>
            <Link v-if="needsConfirmation" :href="securityUrl"
                >Atkārtoti apstiprināt piekļuvi</Link
            >
            <template #footer
                ><button
                    class="btn btn-danger"
                    type="button"
                    :disabled="busy || disabled"
                    @click="confirmRemove"
                >
                    Dzēst
                </button></template
            >
        </Modal>
    </Card>
</template>
