<template>
    <div>
        <Head title="Konta drošība" />
        <p><Link :href="profileUrl">Mans profils</Link></p>
        <div class="row">
            <div class="md:col-6">
                <Card
                    title="Mainīt paroli"
                    icon="lock"
                    card-header-class="card-header-primary"
                >
                    <Form
                        v-bind="passwordForm"
                        reset-on-success
                        reset-on-error
                        v-slot="{ errors, processing, recentlySuccessful }"
                    >
                        <fieldset
                            :disabled="processing || twoFactorSetupActive"
                        >
                            <div class="form-group">
                                <label for="security-current-password"
                                    >Pašreizējā parole</label
                                >
                                <input
                                    id="security-current-password"
                                    name="current_password"
                                    type="password"
                                    class="form-control"
                                    autocomplete="current-password"
                                    required
                                />
                                <InputError
                                    :message="errors.current_password"
                                />
                            </div>
                            <div class="form-group">
                                <label for="security-password"
                                    >Jaunā parole</label
                                >
                                <input
                                    id="security-password"
                                    name="password"
                                    type="password"
                                    class="form-control"
                                    autocomplete="new-password"
                                    :passwordrules="passwordRules"
                                    required
                                />
                                <InputError :message="errors.password" />
                            </div>
                            <div class="form-group">
                                <label for="security-password-confirmation"
                                    >Apstiprināt jauno paroli</label
                                >
                                <input
                                    id="security-password-confirmation"
                                    name="password_confirmation"
                                    type="password"
                                    class="form-control"
                                    autocomplete="new-password"
                                    :passwordrules="passwordRules"
                                    required
                                />
                                <InputError
                                    :message="errors.password_confirmation"
                                />
                            </div>
                            <Checkbox
                                v-if="canManageSessions"
                                id="revoke-other-sessions"
                                v-model:checked="revokeOtherSessions"
                                name="revoke_other_sessions"
                                :value="1"
                                >Izrakstīties no citām ierīcēm pēc paroles
                                maiņas</Checkbox
                            >
                            <button
                                type="submit"
                                class="btn btn-primary"
                                :disabled="processing || twoFactorSetupActive"
                            >
                                {{
                                    processing ? 'Saglabā…' : 'Saglabāt paroli'
                                }}
                            </button>
                        </fieldset>
                        <p v-if="twoFactorSetupActive" class="fg-2">
                            Vispirms pabeidziet vai atceliet 2FA iestatīšanu.
                        </p>
                        <p
                            v-if="recentlySuccessful"
                            class="text-success"
                            role="status"
                        >
                            Parole nomainīta.
                        </p>
                    </Form>
                </Card>
            </div>
            <div class="md:col-6">
                <ManageTwoFactor
                    :can-manage-two-factor="canManageTwoFactor"
                    :two-factor-enabled="twoFactorEnabled"
                    :requires-confirmation="requiresConfirmation"
                    @setup-change="twoFactorSetupActive = $event"
                />
            </div>
        </div>
        <ManagePasskeys
            v-if="canManagePasskeys"
            :passkeys="passkeys"
            :disabled="twoFactorSetupActive"
        />
        <ManageSessions
            v-if="canManageSessions"
            :sessions="sessions"
            :disabled="twoFactorSetupActive"
        />
        <DeleteAccount :disabled="twoFactorSetupActive" />
    </div>
</template>

<script>
import { Form, Head, Link } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';
import InputError from '@scaffold/components/InputError.vue';
import ManageTwoFactor from '@scaffold/components/ManageTwoFactor.vue';
import ManagePasskeys from '@scaffold/components/ManagePasskeys.vue';
import ManageSessions from '@scaffold/components/ManageSessions.vue';
import DeleteAccount from '@scaffold/components/DeleteAccount.vue';
import Checkbox from '@scaffold/components/Checkbox.vue';
import { update } from '@app/routes/user-password';
import { edit } from '@app/routes/profile';

export default {
    name: 'SecuritySettings',
    components: {
        Card,
        Form,
        Head,
        InputError,
        Link,
        ManageTwoFactor,
        ManagePasskeys,
        ManageSessions,
        DeleteAccount,
        Checkbox,
    },
    layout: { pageTitle: 'Konta drošība' },
    props: {
        canManageTwoFactor: Boolean,
        twoFactorEnabled: Boolean,
        requiresConfirmation: Boolean,
        passwordRules: String,
        canManagePasskeys: Boolean,
        passkeys: Array,
        canManageSessions: Boolean,
        sessions: Array,
    },
    data() {
        return {
            passwordForm: update.form(),
            profileUrl: edit.url(),
            twoFactorSetupActive: false,
            revokeOtherSessions: false,
        };
    },
};
</script>
